codon={}; i=0
for a in bases:
    for b in bases:
        for c in bases:
            codon[a+b+c]=aas[i]; i+=1
def tr(s): return ''.join(codon.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

# --- context around the long ORF start ---
print("5' flank (1-160):", seq[:160])
print("codon frame 1 from 1:", [seq[i:i+3] for i in range(0,30,3)])
print("Bases 150-175:", seq[149:175])
# find the stop before the ORF start
f1 = tr(seq[n%3:])  # not needed
# check frame of 158: (158-1)%3=1 -> frame 1
fr = 1
print("Frame-1 codons 50-58 (pos 151-175):", [seq[i:i+3] for i in range(150,174,3)])

# --- full frame-1 translation, mark stops ---
f1_nt = seq[1:]  # frame offset 1
p1 = tr(f1_nt)
print("\nlongest ORF in frame1 =", len(p1), "aa; stops at codon indices:", [i for i,c in enumerate(p1) if c=='*'][:5])

prot = p1[:len(p1)]
# motif search
motifs = {
 'P-type ATPase phosphorylation DKTGTLT':'DKTGTLT',
 'P-type ATPase ATP-binding GDGxND':'GDG',
 'hinge GDGINDAP':'GDGIND',
 'TGES-ish':'TGES',
 'TGD':'TGD',
 'CXXC (metal)':None,
}
for name,m in motifs.items():
    if m:
        for mm in re.finditer('(?=(%s))'%m, prot):
            print(f"{name} '{m}' at protein pos {mm.start()+1} (nt {1+3*mm.start()+1})")

for mm in re.finditer('(?=(C..C))', prot):
    print("CXXC at protein", mm.start()+1, mm.group(1))

# --- ORFs all 6 frames, min 60 aa ---
def orfs(s, minaa=60):
    out=[]
    for f in range(3):
        i=f; start=None
        while i+3<=len(s):
